const users=[{name:'Lucía Fernández',email:'lucia@example.com',initials:'LF',notes:38,last:'Hace 12 minutos',date:'02 oct 2026',status:'Habilitada',role:'Usuario'}, {name:'Martín López',email:'martin@example.com',initials:'ML',notes:24,last:'Hace 35 minutos',date:'03 oct 2026',status:'Habilitada',role:'Usuario'}, {name:'Sofía García',email:'sofia@example.com',initials:'SG',notes:17,last:'Hace 1 hora',date:'05 oct 2026',status:'Habilitada',role:'Analista'}, {name:'Nicolás Romero',email:'nicolas@example.com',initials:'NR',notes:9,last:'Ayer, 18:42',date:'08 oct 2026',status:'Bloqueada',role:'Usuario'}, {name:'Valentina Torres',email:'valentina@example.com',initials:'VT',notes:12,last:'Ayer, 16:10',date:'11 oct 2026',status:'Habilitada',role:'Usuario'}];
const titles={dashboard:'Dashboard',users:'Usuarios',processing:'Procesamientos',audit:'Auditoría'};let page='dashboard';let period='30';
const badge=(status)=>`<span class="badge ${status==='Bloqueada'||status==='Fallido'?'blocked':status==='Pendiente'?'wait':''}">${status}</span>`;
function heading(k,title,desc,controls=''){return `<div class="heading"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p>${desc}</p></div><div class="toolbar">${controls}</div></div>`}
function rows(list){return list.map(u=>`<tr><td><div class="account"><div class="avatar">${u.initials}</div><div>${u.name}<small>${u.email}</small></div></div></td><td>${badge(u.status)}</td><td>${u.notes}</td><td>${u.last}</td><td><button class="table-action" data-user="${users.indexOf(u)}" aria-label="Ver cuenta de ${u.name}">Ver cuenta ↗</button></td></tr>`).join('')}
function userTable(list){return `<div class="table-wrap"><table><thead><tr><th>Usuario</th><th>Estado</th><th>Notas</th><th>Última actividad</th><th></th></tr></thead><tbody id="user-rows">${rows(list)}</tbody></table></div>`}
function dashboard(){const short=period==='7';const cards=[['Usuarios registrados','248','＋ 18','altas en el período'],['Usuarios que escribieron',short?'54':'126',short?'21,8 %':'50,8 %','de los registrados'],['Notas creadas',short?'183':'684','＋ 12,4 %','vs. período anterior'],['Procesamientos exitosos','98,6 %','10 fallidos','en el período']];return heading('VISIÓN GENERAL','El pulso de la plataforma','Una mirada al uso y al funcionamiento de El Espejo.',`<select id="period" aria-label="Período del dashboard"><option value="30" ${short?'':'selected'}>Últimos 30 días</option><option value="7" ${short?'selected':''}>Últimos 7 días</option></select>`)+`<section class="stats">${cards.map(c=>`<article class="card"><div class="card-label">${c[0]}<span>↗</span></div><div class="number">${c[1]}</div><div class="trend">${c[2]} <em>${c[3]}</em></div></article>`).join('')}</section><div class="grid"><section class="panel"><div class="panel-head"><div><h2>Actividad en el tiempo</h2><p class="sub">Usuarios únicos por día · ${short?'10–16 oct':'17 sep–16 oct'} 2026</p></div><div class="legend"><span>Accedieron</span><span>Escribieron</span></div></div><svg class="chart" viewBox="0 0 600 205" role="img" aria-label="Ejemplo de actividad diaria: accesos y escritura aumentan durante el período"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#b8d6ce" stop-opacity=".14"/><stop offset="1" stop-color="#b8d6ce" stop-opacity="0"/></linearGradient></defs><line x1="32" x2="590" y1="22" y2="22"/><line x1="32" x2="590" y1="72" y2="72"/><line x1="32" x2="590" y1="122" y2="122"/><line x1="32" x2="590" y1="172" y2="172"/><text x="0" y="26">60</text><text x="0" y="76">40</text><text x="0" y="126">20</text><text x="6" y="176">0</text><path d="M32 140 L52 129 L72 135 L92 113 L112 119 L132 97 L152 108 L172 87 L192 102 L212 89 L232 107 L252 88 L272 67 L292 85 L312 76 L332 94 L352 71 L372 58 L392 65 L412 42 L432 58 L452 45 L472 62 L492 46 L512 31 L532 46 L552 21 L572 38 L590 29 L590 172 L32 172Z" fill="url(#area)"/><path d="M32 140 L52 129 L72 135 L92 113 L112 119 L132 97 L152 108 L172 87 L192 102 L212 89 L232 107 L252 88 L272 67 L292 85 L312 76 L332 94 L352 71 L372 58 L392 65 L412 42 L432 58 L452 45 L472 62 L492 46 L512 31 L532 46 L552 21 L572 38 L590 29" fill="none" stroke="#b8d6ce" stroke-width="2.5" stroke-linejoin="round"/><path d="M32 160 L52 155 L72 159 L92 146 L112 151 L132 141 L152 146 L172 133 L192 144 L212 130 L232 142 L252 130 L272 119 L292 133 L312 125 L332 137 L352 119 L372 109 L392 117 L412 96 L432 110 L452 97 L472 112 L492 99 L512 86 L532 100 L552 76 L572 88 L590 80" fill="none" stroke="#d5b77e" stroke-width="2.5" stroke-linejoin="round"/></svg><div class="chart-labels">${(short?['10 oct','11 oct','12 oct','13 oct','14 oct','16 oct']:['17 sep','22 sep','27 sep','02 oct','07 oct','16 oct']).map(x=>`<span>${x}</span>`).join('')}</div><div class="chart-note">Accedieron: abrieron la app autenticados. Escribieron: crearon al menos una nota.</div></section><section class="panel"><h2>Cómo llegan las notas</h2><p class="sub">Notas creadas en el período</p>${[['Escritura',short?'112':'418',61],['Audio',short?'59':'218',32],['Importación',short?'12':'48',7]].map(s=>`<div class="source-row"><div class="source-label"><span>${s[0]}</span><span>${s[1]} <span class="sub">· ${s[2]} %</span></span></div><div class="bar"><span style="width:${s[2]}%"></span></div></div>`).join('')}<div class="total"><span>Total de notas creadas</span><strong>${short?'183':'684'}</strong></div><p class="sub" style="margin-top:14px">Existentes en la plataforma: 1.842</p></section></div><section class="panel"><div class="panel-head"><div><h2>Usuarios con actividad reciente</h2><p class="sub">Una vista rápida de las cuentas</p></div><button class="link-button" data-page="users">Ver usuarios →</button></div>${userTable(users.slice(0,3))}</section><div class="info"><strong>Privacidad por diseño.</strong> Este panel muestra metadatos y métricas. El contenido de las notas y los audios permanece fuera del acceso administrativo.</div>`}
function usersPage(){return heading('GESTIÓN DE CUENTAS','Usuarios','Estado de las cuentas y uso de la plataforma.')+`<div class="summary-row"><span><strong>248</strong> registrados</span><span><strong>245</strong> habilitados</span><span><strong>3</strong> bloqueados</span></div><section class="panel"><div class="filter-row"><input id="search" type="search" placeholder="Buscar nombre o correo…" aria-label="Buscar usuarios"><select id="status" aria-label="Filtrar usuarios por estado"><option value="">Todos los estados</option><option>Habilitada</option><option>Bloqueada</option></select></div>${userTable(users)}<p class="sub" style="margin-top:18px" id="result-count">Mostrando 5 cuentas de ejemplo · 248 en la plataforma ficticia</p></section><div class="info">Seleccioná <strong>Ver cuenta</strong> para explorar el detalle. Bloqueo y cambios de rol se muestran como funcionalidades futuras.</div>`}
function processingPage(){return heading('OPERACIÓN','Procesamientos','Estado de las tareas, sin exponer contenido privado.')+`<section class="stats">${[['Completados','704'],['En curso','6'],['Pendientes','3'],['Fallidos','10']].map(x=>`<article class="card"><div class="card-label">${x[0]}</div><div class="number">${x[1]}</div><p class="sub">Últimos 30 días</p></article>`).join('')}</section><section class="panel"><h2>Tareas recientes</h2><div class="table-wrap"><table><thead><tr><th>Tarea</th><th>Identificador</th><th>Estado</th><th>Actualización</th><th>Acción futura</th></tr></thead><tbody>${[['Transcripción','proc_0182','Fallido','Hace 8 minutos'],['Extracción','proc_0181','Completado','Hace 12 minutos'],['Documento','proc_0180','Pendiente','Hace 15 minutos']].map(x=>`<tr><td>${x[0]}</td><td>${x[1]}</td><td>${badge(x[2])}</td><td>${x[3]}</td><td><button disabled class="control">Reintentar</button></td></tr>`).join('')}</tbody></table></div></section>`}
function auditPage(){return heading('TRAZABILIDAD','Auditoría','Historial de acciones administrativas · vista de una etapa futura.')+`<section class="panel"><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Responsable</th><th>Acción</th><th>Cuenta afectada</th><th>Resultado</th></tr></thead><tbody><tr><td>15 oct · 18:42</td><td>Admin de ejemplo</td><td>Bloqueo de cuenta</td><td>nicolas@example.com</td><td>${badge('Completado')}</td></tr><tr><td>14 oct · 10:05</td><td>Admin de ejemplo</td><td>Asignación de rol analista</td><td>sofia@example.com</td><td>${badge('Completado')}</td></tr></tbody></table></div></section><div class="info">Eventos ficticios. En la implementación, cada acción registrará responsable, objetivo, fecha, motivo y resultado.</div>`}
function render(){document.getElementById('main').innerHTML=({dashboard,users:usersPage,processing:processingPage,audit:auditPage})[page]();document.getElementById('breadcrumb').textContent=titles[page];document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);if(b.dataset.page===page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});}
function showUser(i){const u=users[i];document.getElementById('detail-content').innerHTML=`<div class="dialog-head"><div><div class="eyebrow">DETALLE DE CUENTA</div><h2>${u.name}</h2><p>${u.email}</p></div><button class="close" id="close-detail" aria-label="Cerrar detalle">×</button></div>${badge(u.status)}<div class="detail-grid"><div><small>Fecha de registro</small>${u.date}</div><div><small>Última actividad</small>${u.last}</div><div><small>Notas existentes</small>${u.notes}</div><div><small>Rol</small>${u.role}</div></div><div class="info">El contenido de las notas y los audios no está disponible en este panel.</div><div class="detail-section"><h3>Administración de la cuenta</h3><p>Próxima etapa: cambiar el estado con un motivo, revocar sesiones y dejar registro de la acción.</p><button class="control" disabled>${u.status==='Bloqueada'?'Desbloquear':'Bloquear'} cuenta · Próximamente</button></div>`;document.getElementById('detail').showModal();}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-page]');if(nav){page=nav.dataset.page;history.replaceState(null,'','#'+page);render();window.scrollTo(0,0)}const user=e.target.closest('[data-user]');if(user)showUser(Number(user.dataset.user));if(e.target.closest('#close-detail'))document.getElementById('detail').close()});document.addEventListener('change',e=>{if(e.target.id==='period'){period=e.target.value;render()}if(e.target.id==='status')filterUsers()});document.addEventListener('input',e=>{if(e.target.id==='search')filterUsers()});function filterUsers(){const query=document.getElementById('search').value.toLocaleLowerCase('es');const status=document.getElementById('status').value;const list=users.filter(u=>(u.name+' '+u.email).toLocaleLowerCase('es').includes(query)&&(!status||u.status===status));document.getElementById('user-rows').innerHTML=rows(list)||( '<tr><td colspan="5" class="empty">No hay cuentas de ejemplo que coincidan.</td></tr>');document.getElementById('result-count').textContent=`${list.length} cuentas de ejemplo coinciden`;}if(titles[location.hash.slice(1)])page=location.hash.slice(1);render();
